// Builds worker.js (one self-contained file) from src/worker.template.js + src/index.html.
import { readFileSync, writeFileSync } from "node:fs";

const html = readFileSync(new URL("./src/index.html", import.meta.url), "utf8");
const tpl = readFileSync(new URL("./src/worker.template.js", import.meta.url), "utf8");
if (!tpl.includes("__HTML__")) throw new Error("template is missing __HTML__");
const out =
  "// GENERATED by build.mjs. Edit src/ and run `node build.mjs`.\n" +
  tpl.replace("const HTML = __HTML__;", () => `const HTML = ${JSON.stringify(html)};`);
writeFileSync(new URL("./worker.js", import.meta.url), out);
console.log(`worker.js written (${(out.length / 1024).toFixed(1)} KB)`);
